import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.XctAhZuT.js";const o="/docs/images/authoring/audio-tree.svg",i="/docs/images/authoring/_real/10-generate-audio.png",b=JSON.parse('{"title":"音频资产","description":"不满足以上规范的素材可能在客户端解码失败、播放抖动或与 TTS 资源响度失衡。","frontmatter":{"description":"不满足以上规范的素材可能在客户端解码失败、播放抖动或与 TTS 资源响度失衡。"},"headers":[],"relativePath":"authoring/audio-assets.md","filePath":"authoring/audio-assets.md","lastUpdated":1789373514000}'),n={name:"authoring/audio-assets.md"};function l(c,t,r,h,p,u){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="音频资产" tabindex="-1">音频资产 <a class="header-anchor" href="#音频资产" aria-label="Permalink to &quot;音频资产&quot;">​</a></h1><blockquote><p>听力课的音频分两类：引用单词/表达 id 的走<strong>运行时 TTS</strong>（不落盘），具名听力素材落在 <code>assets/sounds/&lt;lang&gt;/listening/&lt;asset&gt;.mp3</code>。具名素材是 Lesson 的可发布依赖，发布前用 <code>audio-manifest</code> 校验引用闭合。</p></blockquote><p><img src="'+o+'" alt="音频目录结构 + manifest 状态色（present / missing）" loading="lazy"></p><p><img src="'+i+`" alt="生成听力音频对话框（实际运行截图：voice / model / speed / force 选项）" loading="lazy"></p><h2 id="audioasset-的两种取值" tabindex="-1"><code>audioAsset</code> 的两种取值 <a class="header-anchor" href="#audioasset-的两种取值" aria-label="Permalink to &quot;\`audioAsset\` 的两种取值&quot;">​</a></h2><table tabindex="0"><thead><tr><th>取值</th><th>解析</th><th>落盘</th></tr></thead><tbody><tr><td>词/表达 id（如 <code>w-merhaba</code>）</td><td>运行时 TTS 朗读该词条</td><td>不落盘</td></tr><tr><td>具名素材（如 <code>s1-dialogue-a</code>）</td><td><code>assets/sounds/&lt;lang&gt;/listening/&lt;asset&gt;.mp3</code></td><td>必须存在</td></tr></tbody></table><p><code>audioAssets</code> 数组同理，可混入 <code>anki://&lt;importId&gt;/&lt;file&gt;</code>（导入的 Anki 媒体，由应用内 Anki 目录解析，不受 manifest 校验）。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assets/sounds/&lt;lang&gt;/</span></span>
<span class="line"><span>└── listening/</span></span>
<span class="line"><span>    ├── &lt;asset&gt;.mp3        # 具名听力素材（生成或人工录音，平铺）</span></span>
<span class="line"><span>    ├── bgm/               # 混音用背景音素材池（bgmA.mp3 …）</span></span>
<span class="line"><span>    ├── debut/             # 混音用开场素材池（debutA.mp3 …）</span></span>
<span class="line"><span>    └── fin/               # 混音用收束素材池（finA.mp3 …）</span></span></code></pre></div><ul><li>具名素材的文件名 = <code>audioAsset</code> 标识符 + <code>.mp3</code>。</li><li><code>bgm/</code>、<code>debut/</code>、<code>fin/</code> 是 <code>tool/mix_listening_a1.py</code> 的混音素材池，不通过 <code>audioAsset</code> 引用。</li></ul><div class="warning custom-block"><p class="custom-block-title">引用与文件必须成对提交</p><p><strong>禁止</strong>仅添加文件而不更新引用；<strong>禁止</strong>仅添加引用而不提交文件。后者在 manifest 中直接标 <code>missing</code> 并阻断发布。</p></div><h2 id="格式规范" tabindex="-1">格式规范 <a class="header-anchor" href="#格式规范" aria-label="Permalink to &quot;格式规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>要求</th></tr></thead><tbody><tr><td>容器</td><td>MP3</td></tr><tr><td>采样率</td><td>44.1 kHz</td></tr><tr><td>声道</td><td>单声道优先；接受立体声</td></tr><tr><td>比特率</td><td>≥ 128 kbps</td></tr><tr><td>前后静音</td><td>各 ≤ 0.3 s</td></tr><tr><td>峰值</td><td>不得削波（true peak ≤ -1 dBTP）</td></tr><tr><td>响度</td><td>与相邻素材差异 ≤ 2 LUFS</td></tr></tbody></table><p>不满足以上规范的素材可能在客户端解码失败、播放抖动或与 TTS 资源响度失衡。</p><h2 id="录音要求" tabindex="-1">录音要求 <a class="header-anchor" href="#录音要求" aria-label="Permalink to &quot;录音要求&quot;">​</a></h2><ul><li>母语者或达到流利程度的说话者。</li><li>环境噪声低且稳定（SNR ≥ 40 dB）。</li><li>麦克风距离 10–20 cm，控制爆破音。</li><li>自然、清晰、面向学习者的语速。</li><li>不使用夸张语调或戏剧化表演。</li><li>不含未经许可的音乐或第三方内容。</li><li>段落之间保留 0.5–1.0 s 自然间隔。</li></ul><h2 id="manifest-校验" tabindex="-1">Manifest 校验 <a class="header-anchor" href="#manifest-校验" aria-label="Permalink to &quot;Manifest 校验&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool/course_cli.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --course-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/courses/turkish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audio-manifest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest.csv</span></span></code></pre></div><p>只统计「具名听力素材」——词/表达 id 引用与 <code>anki://</code> 前缀自动跳过。输出 CSV 列：</p><table tabindex="0"><thead><tr><th>列</th><th>含义</th></tr></thead><tbody><tr><td><code>asset_id</code></td><td>JSON 中引用的标识符</td></tr><tr><td><code>type</code></td><td>固定 <code>listening</code></td></tr><tr><td><code>referenced_by</code></td><td>引用位置（<code>section/unit/lesson</code>）</td></tr><tr><td><code>status</code></td><td><code>present</code>（<code>listening/&lt;asset&gt;.mp3</code> 存在）/ <code>missing</code></td></tr></tbody></table><p>发布门禁：<strong>禁止</strong>存在 <code>status=missing</code> 的引用 —— 先补录或删除引用。</p><h2 id="替换生成音频" tabindex="-1">替换生成音频 <a class="header-anchor" href="#替换生成音频" aria-label="Permalink to &quot;替换生成音频&quot;">​</a></h2><p>人工录音可覆盖同 ID 的 TTS 生成文件。提交说明中标记替换关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 替换 audioAsset: s1-dialogue-a</span></span>
<span class="line"><span>  原: TTS (MiniMax speech-2.8-hd)</span></span>
<span class="line"><span>  新: 人工录音 / 文件: assets/sounds/turkish/listening/s1-dialogue-a.mp3</span></span>
<span class="line"><span>  授权: CC-BY-SA 4.0 / 作者张三</span></span></code></pre></div><p>ID 保持不变，Lesson JSON 无需因音质替换而修改。</p><h2 id="生成听力音频-minimax-tts" tabindex="-1">生成听力音频（MiniMax TTS） <a class="header-anchor" href="#生成听力音频-minimax-tts" aria-label="Permalink to &quot;生成听力音频（MiniMax TTS）&quot;">​</a></h2><p>工具栏 <strong>「生成听力音频」</strong> 扫描当前课程所有听力课的 <code>listeningPhases</code>，对有 <code>transcript</code> 的 phase 调 MiniMax TTS 生成缺失的 MP3。底层脚本是 <code>tool/generate_audio.py</code>（子命令 <code>all</code> / <code>list</code> / <code>speak</code>），GUI 以子进程方式调用并显式传 <code>--course-dir</code> / <code>--sounds-dir</code>。</p><h3 id="预览" tabindex="-1">预览 <a class="header-anchor" href="#预览" aria-label="Permalink to &quot;预览&quot;">​</a></h3><p>打开对话框前先调 <code>generate_audio_client.preview_generation(course_dir, settings)</code> 返回 <code>{total, existing}</code> —— <code>total</code> 是可生成的 phase 数（缺 <code>audioAsset</code> 或 <code>transcript</code> 的不计入），<code>existing</code> 是已存在 MP3 的数量。</p><h3 id="对话框字段" tabindex="-1">对话框字段 <a class="header-anchor" href="#对话框字段" aria-label="Permalink to &quot;对话框字段&quot;">​</a></h3><p><code>GenerateAudioDialog</code>（<code>tool/gui/src/dialogs/generate_audio_dialog.py</code>）暴露：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>约束 / 默认</th></tr></thead><tbody><tr><td><code>voice_id</code></td><td>可编辑下拉</td><td>内置常见 MiniMax 音色（<code>female-tianmei</code> 等）；默认 <code>female-tianmei</code></td></tr><tr><td><code>model</code></td><td>自由文本</td><td>默认 <code>speech-2.8-hd</code></td></tr><tr><td><code>speed</code></td><td>float</td><td>[0.5, 2.0]，默认 <strong>0.9</strong></td></tr><tr><td><code>force</code></td><td>bool</td><td>强制重生成已存在的 MP3（默认关，保护人工录音）</td></tr><tr><td><code>api_key</code></td><td>string</td><td><strong>仅当前会话内存</strong>；关闭即清空，不入 QSettings</td></tr></tbody></table><p><code>voice_id</code> / <code>model</code> / <code>speed</code> / <code>force</code> 持久化到 QSettings（<code>tts/*</code>）；<code>api_key</code> 永不落盘。</p><h3 id="执行" tabindex="-1">执行 <a class="header-anchor" href="#执行" aria-label="Permalink to &quot;执行&quot;">​</a></h3><p><code>GenerateAudioWorker</code>（<code>tool/gui/src/application/audio_worker.py</code>）在线程中跑子进程，逐条生成并回报进度；<code>job_tray</code> 在工具栏右侧显示「正在生成听力音频…」，<code>QProgressDialog</code> 提供取消（已生成文件保留）。失败项记 telemetry，需在设置 → 操作日志查看明细后人工处置 —— 没有自动 fallback 链，失败即跳过。</p><h2 id="授权" tabindex="-1">授权 <a class="header-anchor" href="#授权" aria-label="Permalink to &quot;授权&quot;">​</a></h2><p>提交者必须：</p><ul><li>拥有录音版权或有效授权。</li><li>允许项目长期、免版税地随 Turna 分发。</li><li>不含未授权背景音乐或第三方素材。</li><li>在 <code>release-notes</code> 中标注授权协议（CC-BY / CC-BY-SA / 自有版权等）。</li></ul><h2 id="录音-qa-清单" tabindex="-1">录音 QA 清单 <a class="header-anchor" href="#录音-qa-清单" aria-label="Permalink to &quot;录音 QA 清单&quot;">​</a></h2><p>发布前逐项核对：</p><ul><li>[ ] 资产在 manifest 中 <code>status=present</code>。</li><li>[ ] JSON 引用与文件名严格一致（大小写敏感）。</li><li>[ ] 文件可在目标设备解码（<code>ffmpeg -i &lt;file&gt;</code> 验证）。</li><li>[ ] 响度与相邻素材差异 ≤ 2 LUFS。</li><li>[ ] 无超长静音（&gt; 0.5 s 的内部静音需剪辑）。</li><li>[ ] 听力题具有重播按钮与必要文本边界。</li><li>[ ] 高频段无金属感、底噪稳定。</li></ul><h2 id="故障与处置" tabindex="-1">故障与处置 <a class="header-anchor" href="#故障与处置" aria-label="Permalink to &quot;故障与处置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>客户端无法播放</td><td>编解码或采样率异常</td><td><code>ffprobe</code> 检查并重导出</td></tr><tr><td>响度跳跃</td><td>录音条件不一致</td><td>在 DAW 中归一化至 -16 LUFS</td></tr><tr><td>引用了不存在的文件</td><td>删除录音未联动</td><td>manifest 标 <code>missing</code>；删除引用或补录</td></tr><tr><td>客户端解码抖动</td><td>MP3 VBR 极端设置</td><td>重导出为 CBR 192 kbps</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/audio-and-tts">音频、TTS 与朗读</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/authoring/release-checklist">发布检查表</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li></ul>`,45)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
